package com.mr486.msplatform.consumer.controller;
import lombok.RequiredArgsConstructor;import org.springframework.http.HttpHeaders;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.reactive.function.client.WebClient;import reactor.core.publisher.Mono;import java.util.*;
@RestController @RequiredArgsConstructor @RequestMapping("/api")
public class AggregateController{ private final WebClient.Builder webClientBuilder; @GetMapping("/aggregate") @PreAuthorize("hasRole('ADMIN')") public Mono<Map<String,String>> aggregate(@RequestHeader(HttpHeaders.AUTHORIZATION) String authorization){ return Mono.zip(webClientBuilder.build().get().uri("lb://service-a/api/resources-a").header(HttpHeaders.AUTHORIZATION, authorization).retrieve().bodyToMono(String.class),webClientBuilder.build().get().uri("lb://service-b/api/resources-b").header(HttpHeaders.AUTHORIZATION, authorization).retrieve().bodyToMono(String.class),webClientBuilder.build().get().uri("lb://service-c/api/resources-c").header(HttpHeaders.AUTHORIZATION, authorization).retrieve().bodyToMono(String.class)).map(tuple->{ Map<String,String> result=new LinkedHashMap<>(); result.put("service-a", tuple.getT1());result.put("service-b", tuple.getT2());result.put("service-c", tuple.getT3()); return result; }); }}
